    let d = c as int
    if d >= 48 && d <= 57 {
        d - 48
    } else if d >= 65 && d <= 90 {
        d - 55
    } else if d >= 97 && d <= 122 {
        d - 87
    } else {
        0
    }
}

fn digit_char(v: int) -> string {
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let i = v as usize
    let s: string = digits[i..i + 1].to_string()
    s
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse().unwrap_or(10)
        let to: int = parts[2].parse().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out = ""
        while n > 0 {
            out = digit_char(n % to) + out
            n = n / to
        }
        println(out)
    }
}

